// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading for safe Render mapping
const { fontFamily: montserratFamily } = loadMontserrat();



export type RhythmPatternProps = Record<string, any>;

const generateHybridPath = (w: number, y: number, offset: number, ampMultiplier: number) => {
  const c = w / 2 + offset;
  const peak1 = y - 280 * ampMultiplier;
  const peak2 = y + 320 * ampMultiplier;
  const peak3 = y - 200 * ampMultiplier;
  const smoothMid1 = y + 120 * ampMultiplier;

  // Uses purely spaces to avoid any potential SVG path parsing issues
  return `M 0 ${y} L ${c - 400} ${y} C ${c - 300} ${y} ${c - 250} ${y - 80 * ampMultiplier} ${c - 150} ${smoothMid1} L ${c - 80} ${peak1} L ${c + 10} ${peak2} L ${c + 80} ${peak3} C ${c + 180} ${y + 100 * ampMultiplier} ${c + 280} ${y} ${c + 400} ${y} L ${w} ${y}`;
};

const RhythmPattern: React.FC<RhythmPatternProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 10,
  lightBlueLineColor = "#38bdf8",
  deepBlueAccentColor = "#1e3a8a",
  textColor = "#ffffff",
  showText = true,
  textElements = ["BEAT", "RHYTHM", "PATTERN"],
  lineThickness = 3.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;

  // Proportional Timings mapped safely across dynamic duration
  const tWaveformStart = totalFrames * 0.15;
  const tWaveformDur = totalFrames * 0.25;

  const tDotsStart = totalFrames * 0.40;
  const tDotsDur = totalFrames * 0.25;

  const tGridLinesStart = totalFrames * 0.50;
  const tGridLinesDur = totalFrames * 0.25;

  // Base canvas resolution config
  const bg = transparentBackground ? "transparent" : backgroundColor;

  // Deterministic procedural waveforms
  const pathMain = useMemo(() => generateHybridPath(width, height / 2, 0, 1), [width, height]);
  const pathSub1 = useMemo(() => generateHybridPath(width, height / 2 + 20, -50, 0.6), [width, height]);
  const pathSub2 = useMemo(() => generateHybridPath(width, height / 2 - 20, 50, 0.4), [width, height]);

  // Path evolutions driven by frame progress
  const progMain = interpolate(frame, [tWaveformStart, tWaveformStart + tWaveformDur], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const evolMain = evolvePath(progMain, pathMain);

  const progSub1 = interpolate(frame, [tWaveformStart + 15, tWaveformStart + 15 + tWaveformDur], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const evolSub1 = evolvePath(progSub1, pathSub1);

  const progSub2 = interpolate(frame, [tWaveformStart + 30, tWaveformStart + 30 + tWaveformDur], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const evolSub2 = evolvePath(progSub2, pathSub2);

  // Geometric Pattern Settings
  const gridSize = 60;
  const cols = Math.floor(width / gridSize) + 1;
  const rows = Math.floor(height / gridSize) + 1;
  const maxDist = Math.sqrt((width / 2) ** 2 + (height / 2) ** 2);

  const dots = useMemo(() => {
    const arr = [];
    for (let i = 0; i <= rows; i++) {
      for (let j = 0; j <= cols; j++) {
        arr.push({ x: j * gridSize, y: i * gridSize });
      }
    }
    return arr;
  }, [rows, cols, gridSize]);

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      
      {/* Background Ambience Layer */}
      {!transparentBackground && (
        <svg style={{ position: "absolute", width: "100%", height: "100%", pointerEvents: "none" }}>
          <defs>
            <radialGradient id="bgGlow" cx="50%" cy="50%" r="60%">
              <stop offset="0%" stopColor={deepBlueAccentColor} stopOpacity={0.25} />
              <stop offset="100%" stopColor={deepBlueAccentColor} stopOpacity={0} />
            </radialGradient>
          </defs>
          <rect width="100%" height="100%" fill="url(#bgGlow)" />
        </svg>
      )}

      {/* Repeating Pattern Grid Lines (Phase 3) */}
      <svg style={{ position: "absolute", width: "100%", height: "100%", opacity: 0.15 }}>
        {Array.from({ length: rows + 1 }).map((_, i) => {
          const y = i * gridSize;
          const startFrame = tGridLinesStart + (i / rows) * tGridLinesDur * 0.5;
          if (frame < startFrame - 5) return null;
          
          const expandW = interpolate(frame, [startFrame, startFrame + 40], [0, width / 2], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          return <line key={`h-${i}`} x1={width / 2 - expandW} y1={y} x2={width / 2 + expandW} y2={y} stroke={lightBlueLineColor} strokeWidth={1} />;
        })}
        {Array.from({ length: cols + 1 }).map((_, i) => {
          const x = i * gridSize;
          const startFrame = tGridLinesStart + (i / cols) * tGridLinesDur * 0.5;
          if (frame < startFrame - 5) return null;
          
          const expandH = interpolate(frame, [startFrame, startFrame + 40], [0, height / 2], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          return <line key={`v-${i}`} x1={x} y1={height / 2 - expandH} x2={x} y2={height / 2 + expandH} stroke={lightBlueLineColor} strokeWidth={1} />;
        })}
      </svg>

      {/* Cinematic Pulse Rings (Phase 1) */}
      {[0, 1, 2].map(i => {
        const delay = i * (totalFrames * 0.05);
        if (frame < delay - 5) return null;

        const progress = spring({
          frame: frame - delay,
          fps,
          config: { damping: 100, mass: 2, stiffness: 30 },
          durationInFrames: 120
        });

        const scale = interpolate(progress, [0, 1], [0.1, 5]);
        const opacity = interpolate(progress, [0, 0.3, 1], [0, 0.4, 0], { extrapolateRight: "clamp" });

        return (
          <div key={`ring-${i}`} style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: 200,
            height: 200,
            marginLeft: -100,
            marginTop: -100,
            borderRadius: "50%",
            border: `${lineThickness}px solid ${lightBlueLineColor}`,
            transform: `scale(${scale})`,
            opacity: opacity,
            filter: `drop-shadow(0 0 10px ${lightBlueLineColor})`
          }} />
        )
      })}

      {/* Connecting Geometric Dots (Phase 3) */}
      <svg style={{ position: "absolute", width: "100%", height: "100%" }}>
        {dots.map((dot, index) => {
          const dx = dot.x - width / 2;
          const dy = dot.y - height / 2;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const delay = tDotsStart + (dist / maxDist) * tDotsDur;

          if (frame < delay - 5) return null;

          const dotScale = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14 }
          });
          const dotOpacity = interpolate(frame, [delay, delay + 20], [0, 0.5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

          return (
            <circle
              key={`dot-${index}`}
              cx={dot.x}
              cy={dot.y}
              r={1.5 * dotScale}
              fill={lightBlueLineColor}
              opacity={dotOpacity}
              style={{ filter: `drop-shadow(0 0 4px ${lightBlueLineColor})` }}
            />
          );
        })}
      </svg>

      {/* Evolving Waveform Lines (Phase 2) */}
      <svg style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible" }}>
        <path
          d={pathSub1}
          stroke={deepBlueAccentColor}
          strokeWidth={lineThickness * 0.8}
          fill="none"
          strokeDasharray={evolSub1.strokeDasharray}
          strokeDashoffset={evolSub1.strokeDashoffset}
          style={{ opacity: 0.8, filter: `drop-shadow(0 0 6px ${deepBlueAccentColor})` }}
        />
        <path
          d={pathSub2}
          stroke={lightBlueLineColor}
          strokeWidth={lineThickness * 0.6}
          fill="none"
          strokeDasharray={evolSub2.strokeDasharray}
          strokeDashoffset={evolSub2.strokeDashoffset}
          style={{ opacity: 0.6, filter: `drop-shadow(0 0 4px ${lightBlueLineColor})` }}
        />
        <path
          d={pathMain}
          stroke={lightBlueLineColor}
          strokeWidth={lineThickness}
          fill="none"
          strokeDasharray={evolMain.strokeDasharray}
          strokeDashoffset={evolMain.strokeDashoffset}
          style={{ filter: `drop-shadow(0 0 12px ${lightBlueLineColor})` }}
        />
      </svg>

      {/* Mindful Text Sequence overlay */}
      {showText && textElements.length > 0 && (
        <div style={{
          position: "absolute",
          bottom: height * 0.15,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: "60px",
          fontFamily: montserratFamily,
          fontWeight: 800,
          fontSize: "28px",
          color: textColor,
          letterSpacing: "10px",
          textTransform: "uppercase",
          zIndex: 10
        }}>
          {textElements.map((word, i) => {
            const step = 0.4 / Math.max(1, (textElements.length - 1));
            const startFrame = totalFrames * (0.15 + i * step);

            const wordOpacity = interpolate(frame, [startFrame, startFrame + 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const wordY = interpolate(spring({ frame: frame - startFrame, fps, config: { damping: 15 } }), [0, 1], [30, 0]);

            return (
              <div key={i} style={{
                opacity: wordOpacity,
                transform: `translateY(${wordY}px)`,
                textShadow: `0 0 16px ${lightBlueLineColor}`
              }}>
                {word}
              </div>
            )
          })}
        </div>
      )}

    </AbsoluteFill>
  );
};

export default RhythmPattern;